import React, { useMemo, useEffect, useRef } from 'react';
import { tsneProjection } from '../algorithms/contrastiveLearning';
import './EmbeddingVisualization.css';

function EmbeddingVisualization({ embeddings, activeSensors }) {
  const canvasRef = useRef(null);

  const projections = useMemo(() => {
    const embList = Object.entries(embeddings).map(([sensor, emb]) => ({
      sensor,
      embedding: emb
    }));

    if (embList.length === 0) return [];

    // Perform t-SNE projection
    const embeddingVectors = embList.map(e => e.embedding);
    const projected = tsneProjection(embeddingVectors, 30, 200);

    return embList.map((item, i) => ({
      sensor: item.sensor,
      x: projected[i][0],
      y: projected[i][1]
    }));
  }, [embeddings]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // Clear canvas
    ctx.fillStyle = '#0a0a0f';
    ctx.fillRect(0, 0, width, height);

    // Draw grid
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const x = (i / 10) * width;
      const y = (i / 10) * height;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // Draw axes
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width / 2, 0);
    ctx.lineTo(width / 2, height);
    ctx.moveTo(0, height / 2);
    ctx.lineTo(width, height / 2);
    ctx.stroke();

    // Draw embeddings
    const sensorColors = {
      'DIGIT': '#00d4ff',
      'GelSight': '#7b2ff7',
      'ReSkin': '#ff6b00'
    };

    projections.forEach((proj, idx) => {
      const x = ((proj.x + 1) / 2) * width;
      const y = ((proj.y + 1) / 2) * height;

      const color = sensorColors[proj.sensor] || '#ffffff';

      // Draw glow
      const gradient = ctx.createRadialGradient(x, y, 0, x, y, 20);
      gradient.addColorStop(0, color + '80');
      gradient.addColorStop(1, color + '00');
      ctx.fillStyle = gradient;
      ctx.fillRect(x - 20, y - 20, 40, 40);

      // Draw point
      ctx.beginPath();
      ctx.arc(x, y, 6, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Draw label
      ctx.fillStyle = '#ffffff';
      ctx.font = '11px Inter';
      ctx.fillText(proj.sensor, x + 10, y - 10);
    });

    // Draw connections between different sensors
    if (projections.length >= 2) {
      for (let i = 0; i < projections.length; i++) {
        for (let j = i + 1; j < projections.length; j++) {
          if (projections[i].sensor !== projections[j].sensor) {
            const x1 = ((projections[i].x + 1) / 2) * width;
            const y1 = ((projections[i].y + 1) / 2) * height;
            const x2 = ((projections[j].x + 1) / 2) * width;
            const y2 = ((projections[j].y + 1) / 2) * height;

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.lineWidth = 1;
            ctx.setLineDash([5, 5]);
            ctx.stroke();
            ctx.setLineDash([]);
          }
        }
      }
    }

  }, [projections]);

  return (
    <div className="embedding-visualization">
      <canvas
        ref={canvasRef}
        width={600}
        height={450}
        className="embedding-canvas"
      />

      <div className="embedding-legend">
        <h4>Sensor Types</h4>
        {activeSensors.map(sensor => (
          <div key={sensor} className="embedding-legend-item">
            <div
              className="embedding-color-indicator"
              style={{
                background: sensor === 'DIGIT' ? '#00d4ff' :
                           sensor === 'GelSight' ? '#7b2ff7' : '#ff6b00'
              }}
            />
            <span>{sensor}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

export default EmbeddingVisualization;
